var (
	pas      page.Pages
	branches = make(map[string]bool)
)

include := q.Include
if include == nil {
	include = pagePredicates.ShouldListLocal
}

w := &doctree.NodeShiftTreeWalker[contentNodeI]{
	Tree:   m.treePages,
	Prefix: prefix,
	Handle: func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
		if q.Recursive {
			if p, ok := n.(*pageState); ok && include(p) {
				pas = append(pas, p)
			}
			return false, nil
		}

		// We store both leafs and branches in the same tree, so for non-recursive walks,
		// we need to walk until the end, but can skip
		// any not belonging to child branches.
		// Note that sibling branches may sort before and after each other's
		// descendants (e.g. "s1-foo" sorts before "s1/p1"), so we need to
		// check all ancestors and not just the last branch seen.
		for parent := paths.Dir(key); parent != q.Path && parent != "/" && parent != ""; parent = paths.Dir(parent) {
			if branches[parent] {
				return false, nil
			}
		}

		if p, ok := n.(*pageState); ok && include(p) {
			pas = append(pas, p)
		}

		if n.isContentNodeBranch() {
			branches[key] = true
		}

		return false, nil
	},
}

